import { exportProjectCSV, exportProjectsExcel, exportProjectTimeEntryCSV, exportProjectTimeEntryExcel, exportSummaryReportCSV, exportSummaryReportExcel, exportTimeEntriesCSV, exportTimeEntriesExcel, exportTimeEntryByDateExcel, } from "#controllers/export.controller.js";
import { authMiddleware } from "#middlewares/auth.middleware.js";
import express from "express";
const router = express.Router();
router.get("/project/csv", authMiddleware, exportProjectCSV);
router.get("/project/excel", authMiddleware, exportProjectsExcel);
router.get("/timeEntry/csv", authMiddleware, exportTimeEntriesCSV);
router.get("/timeEntry/excel", authMiddleware, exportTimeEntriesExcel);
router.get("/projectEntries/:projectId/csv", authMiddleware, exportProjectTimeEntryCSV);
router.get("/projectEntries/:projectId/excel", authMiddleware, exportProjectTimeEntryExcel);
router.get("/summary/csv", authMiddleware, exportSummaryReportCSV);
router.get("/summary/excel", authMiddleware, exportSummaryReportExcel);
router.get("/entriesByDate/:startDate/:endDate/excel", authMiddleware, exportTimeEntryByDateExcel);
export default router;
